"use strict";
// Published theory only; no exercise answers or grading data. Generated by scripts/build_reported_rule.py.
const REPORTED_RULE_CONTENT = "<div class=\"mv rsp\" id=\"rsp-root\" lang=\"ru\">\n\n<header class=\"mv-hero\">\n  <h1>Reported Speech</h1>\n  <p>Как пересказать чужие слова: сообщение, вопрос или просьбу. Здесь только главное: схемы, примеры и ловушки. Исключения и все 20 подтем собраны в полном справочнике.</p>\n  <div class=\"mv-chips\">\n    <span class=\"mv-chip\">said · told · asked</span><span class=\"mv-chip\">сдвиг времени</span><span class=\"mv-chip\">точка зрения</span>\n    <span class=\"mv-chip\">вопросы</span><span class=\"mv-chip\">to + глагол</span><span class=\"mv-chip\">reporting verbs</span>\n  </div>\n  <div class=\"mv-pair rsp-demo\">\n    <div><h4>Прямая речь</h4><span class=\"mv-ex\">Maya: “<span class=\"mv-m\">I am</span> ready.”</span></div>\n    <div><h4>Косвенная речь</h4><span class=\"mv-ex\">Maya said <span class=\"mv-m\">she was</span> ready.</span></div>\n  </div>\n  <p class=\"rsp-hero-link\"><a class=\"rsp-more\" href=\"content/theory/reported-full.html\" target=\"_blank\" rel=\"noopener\">Полный справочник: 20 подтем →</a></p>\n</header>\n\n<nav class=\"mv-nav\" aria-label=\"Разделы правила\">\n  <a href=\"#rsp-r1\">1 Конструкция</a><a href=\"#rsp-r2\">2 Время</a><a href=\"#rsp-r3\">3 Точка зрения</a><a href=\"#rsp-r4\">4 Вопросы</a>\n  <a href=\"#rsp-r5\">5 Просьбы</a><a href=\"#rsp-r6\">6 Reporting verbs</a><a href=\"#rsp-r7\">7 Проверка</a>\n</nav>\n\n<section class=\"mv-sec\" id=\"rsp-r1\">\n  <span id=\"rs01\"></span><span id=\"rs02\"></span>\n  <h2><span class=\"mv-num\">1</span>Выберите конструкцию</h2>\n  <p class=\"mv-lead\">Сначала решите, что именно вы передаёте. От этого зависит всё остальное.</p>\n  <div class=\"mv-grid rsp-g4\">\n    <div class=\"mv-card\"><b class=\"mv-ic\">💬</b><h4>Сообщение</h4><p><span class=\"mv-m\">said (that)</span> + сообщение</p><span class=\"mv-ex\">She said she was ready.</span></div>\n    <div class=\"mv-card\"><b class=\"mv-ic\">✉️</b><h4>Сообщение адресату</h4><p><span class=\"mv-m\">told someone (that)</span> + сообщение</p><span class=\"mv-ex\">She told me she was ready.</span></div>\n    <div class=\"mv-card\"><b class=\"mv-ic\">❓</b><h4>Вопрос</h4><p><span class=\"mv-m\">asked</span> + if / whether / wh-word</p><span class=\"mv-ex\">She asked where I lived.</span></div>\n    <div class=\"mv-card\"><b class=\"mv-ic\">🙏</b><h4>Просьба или команда</h4><p><span class=\"mv-m\">asked / told someone to</span> + глагол</p><span class=\"mv-ex\">She asked me to wait.</span></div>\n  </div>\n  <div class=\"mv-note\">После <span class=\"mv-m\">told</span> всегда нужен адресат: <span class=\"mv-ok\">told me</span>. Не <span class=\"mv-x\">told that</span> и не <span class=\"mv-x\">said me</span>.</div>\n  <p class=\"mv-foot\"><a class=\"rsp-more\" href=\"content/theory/reported-full.html#rs01\" target=\"_blank\" rel=\"noopener\">Подробнее: say, tell, ask →</a></p>\n</section>\n\n<section class=\"mv-sec\" id=\"rsp-r2\">\n  <span id=\"rs03\"></span><span id=\"rs04\"></span><span id=\"rs08\"></span>\n  <h2><span class=\"mv-num\">2</span>Время: шаг назад</h2>\n  <p class=\"mv-lead\">Если пересказ идёт в прошлом, глагол обычно «отступает» на один шаг назад.</p>\n  <div class=\"mv-scroll\"><table class=\"mv-table\">\n    <thead><tr><th>Было</th><th>Становится</th><th>Пример</th></tr></thead>\n    <tbody>\n      <tr><td>Present</td><td><span class=\"mv-tag mv-t-ab\">Past</span></td><td><span class=\"mv-ex\">“I work here.” → She said she <span class=\"mv-m\">worked</span> there.</span></td></tr>\n      <tr><td>Past · Present Perfect</td><td><span class=\"mv-tag mv-t-pr\">Past Perfect</span></td><td><span class=\"mv-ex\">“I have finished.” → She said she <span class=\"mv-m\">had finished</span>.</span></td></tr>\n      <tr><td>will · can · may</td><td><span class=\"mv-tag mv-t-ad\">would · could · might</span></td><td><span class=\"mv-ex\">“I can help.” → She said she <span class=\"mv-m\">could</span> help.</span></td></tr>\n      <tr><td>Past Perfect · would · could · should · might</td><td><span class=\"mv-tag mv-t-pe\">без сдвига</span></td><td><span class=\"mv-ex\">“I had left.” → She said she <span class=\"mv-m\">had left</span>.</span></td></tr>\n    </tbody>\n  </table></div>\n  <h3>Когда сдвиг не нужен</h3>\n  <div class=\"mv-pair\">\n    <div><h4>Глагол сообщения в настоящем</h4><span class=\"mv-ex\">Maya <span class=\"mv-m\">says</span> she is tired.</span></div>\n    <div><h4>Информация всё ещё верна</h4><span class=\"mv-ex\">Maya said she <span class=\"mv-m\">lives</span> near the park.</span><span class=\"mv-tr\">Вариант lived тоже допустим.</span></div>\n  </div>\n  <div class=\"mv-note\">Must зависит от смысла: обязанность → <span class=\"mv-m\">had to</span>, вывод → остаётся <span class=\"mv-m\">must</span>.</div>\n  <p class=\"mv-foot\"><a class=\"rsp-more\" href=\"content/theory/reported-full.html#rs03\" target=\"_blank\" rel=\"noopener\">Подробнее: Continuous, Perfect, модальные →</a></p>\n</section>\n\n<section class=\"mv-sec\" id=\"rsp-r3\">\n  <span id=\"rs05\"></span><span id=\"rs06\"></span><span id=\"rs07\"></span>\n  <h2><span class=\"mv-num\">3</span>Точка зрения: кто, когда, где</h2>\n  <p class=\"mv-lead\">Меняется не только время, но и всё, что зависит от того, кто и когда пересказывает.</p>\n  <div class=\"mv-grid\">\n    <div class=\"mv-card\"><b class=\"mv-ic\">👤</b><h4>Кто говорит и кому?</h4><p>I / you / we, my / your / our зависят от участников.</p><span class=\"mv-ex\">Maya: “I lost <span class=\"mv-m\">my</span> key.” → Maya said she had lost <span class=\"mv-m\">her</span> key.</span></div>\n    <div class=\"mv-card\"><b class=\"mv-ic\">🕐</b><h4>Когда пересказываем?</h4><p>today → that day<br>tomorrow → the next day<br>yesterday → the day before</p><span class=\"mv-ex\">“I leave tomorrow.” → She said she would leave <span class=\"mv-m\">the next day</span>.</span></div>\n    <div class=\"mv-card\"><b class=\"mv-ic\">📍</b><h4>Где пересказываем?</h4><p>here → there<br>this / these → that / those</p><span class=\"mv-ex\">“I work here.” → She said she worked <span class=\"mv-m\">there</span>.</span></div>\n  </div>\n  <div class=\"mv-note\">Это не автозамена. Если день, место и участники те же, <span class=\"mv-m\">today, here, I</span> остаются.</div>\n  <p class=\"mv-foot\"><a class=\"rsp-more\" href=\"content/theory/reported-full.html#rs05\" target=\"_blank\" rel=\"noopener\">Подробнее: участники, время и место →</a></p>\n</section>\n\n<section class=\"mv-sec\" id=\"rsp-r4\">\n  <span id=\"rs09\"></span><span id=\"rs10\"></span>\n  <h2><span class=\"mv-num\">4</span>Вопросы: прямой порядок слов</h2>\n  <p class=\"mv-lead\">В косвенном вопросе нет инверсии и нет do / does / did.</p>\n  <div class=\"mv-scroll\"><table class=\"mv-table\">\n    <thead><tr><th>Тип</th><th>Модель</th><th>Пример</th></tr></thead>\n    <tbody>\n      <tr><td>Общий</td><td>asked + <span class=\"mv-m\">if / whether</span> + S + V</td><td><span class=\"mv-ex\">“Do you work?” → She asked <span class=\"mv-m\">if I worked</span>.</span></td></tr>\n      <tr><td>Специальный</td><td>asked + <span class=\"mv-m\">wh-word</span> + S + V</td><td><span class=\"mv-ex\">“Where do you work?” → She asked <span class=\"mv-m\">where I worked</span>.</span></td></tr>\n      <tr><td>Who — подлежащее</td><td>asked + <span class=\"mv-m\">who</span> + V</td><td><span class=\"mv-ex\">“Who called?” → She asked <span class=\"mv-m\">who had called</span>.</span></td></tr>\n    </tbody>\n  </table></div>\n  <div class=\"mv-note mv-warn\"><span class=\"mv-x\">She asked where did I work.</span> <span class=\"mv-ok\">She asked where I worked.</span></div>\n  <p class=\"mv-foot\"><a class=\"rsp-more\" href=\"content/theory/reported-full.html#rs09\" target=\"_blank\" rel=\"noopener\">Подробнее: общие и специальные вопросы →</a></p>\n</section>\n\n<section class=\"mv-sec\" id=\"rsp-r5\">\n  <span id=\"rs11\"></span><span id=\"rs12\"></span><span id=\"rs13\"></span>\n  <h2><span class=\"mv-num\">5</span>Просьбы и команды: to + глагол</h2>\n  <p class=\"mv-lead\">Просьба или приказ превращается в инфинитив с to.</p>\n  <div class=\"mv-grid\">\n    <div class=\"mv-card\"><b class=\"mv-ic\">➕</b><h4>Сделать</h4><p>asked / told + кто + <span class=\"mv-m\">to do</span></p><span class=\"mv-ex\">“Please wait.” → She asked me <span class=\"mv-m\">to wait</span>.</span></div>\n    <div class=\"mv-card\"><b class=\"mv-ic\">➖</b><h4>Не делать</h4><p>asked / told + кто + <span class=\"mv-m\">not to do</span></p><span class=\"mv-ex\">“Don’t leave.” → She told me <span class=\"mv-m\">not to leave</span>.</span></div>\n    <div class=\"mv-card\"><b class=\"mv-ic\">🤝</b><h4>Вежливая просьба</h4><p>asked + кто + <span class=\"mv-m\">to do</span></p><span class=\"mv-ex\">“Could you help me?” → She asked me <span class=\"mv-m\">to help</span> her.</span></div>\n  </div>\n  <div class=\"mv-note\">Конструкцию выбирает смысл: “Can you swim?” — вопрос об умении, “Can you open the door?” — просьба.</div>\n  <p class=\"mv-foot\"><a class=\"rsp-more\" href=\"content/theory/reported-full.html#rs11\" target=\"_blank\" rel=\"noopener\">Подробнее: просьбы, команды и запреты →</a></p>\n</section>\n\n<section class=\"mv-sec\" id=\"rsp-r6\">\n  <span id=\"rs14\"></span><span id=\"rs15\"></span><span id=\"rs16\"></span><span id=\"rs17\"></span><span id=\"rs18\"></span><span id=\"rs19\"></span>\n  <h2><span class=\"mv-num\">6</span>Reporting verbs: смотрите на управление</h2>\n  <p class=\"mv-lead\">После каждого глагола нужна своя конструкция. Её определяет сам глагол.</p>\n  <div class=\"mv-scroll\"><table class=\"mv-table\">\n    <thead><tr><th>После глагола</th><th>Частые глаголы</th><th>Пример</th></tr></thead>\n    <tbody>\n      <tr><td><span class=\"mv-tag mv-t-ab\">to do</span></td><td>promise, offer, agree, refuse</td><td><span class=\"mv-ex\">She promised <span class=\"mv-m\">to help</span>.</span></td></tr>\n      <tr><td><span class=\"mv-tag mv-t-ad\">someone + to do</span></td><td>advise, remind, warn</td><td><span class=\"mv-ex\">She advised <span class=\"mv-m\">me to wait</span>.</span></td></tr>\n      <tr><td><span class=\"mv-tag mv-t-pr\">doing</span></td><td>suggest, admit, deny</td><td><span class=\"mv-ex\">She suggested <span class=\"mv-m\">waiting</span>.</span></td></tr>\n      <tr><td><span class=\"mv-tag mv-t-pe\">предлог + doing</span></td><td>apologise for, insist on</td><td><span class=\"mv-ex\">She apologised <span class=\"mv-m\">for being late</span>.</span></td></tr>\n      <tr><td><span class=\"mv-tag mv-t-of\">that + S + V</span></td><td>explain, confirm, announce</td><td><span class=\"mv-ex\">She explained <span class=\"mv-m\">that she was late</span>.</span></td></tr>\n    </tbody>\n  </table></div>\n  <div class=\"mv-note\">У многих глаголов несколько моделей: <span class=\"mv-m\">suggested waiting</span> и <span class=\"mv-m\">suggested that we wait</span>. Но не <span class=\"mv-x\">suggested me to wait</span>.</div>\n  <p class=\"mv-foot\"><a class=\"rsp-more\" href=\"content/theory/reported-full.html#rs14\" target=\"_blank\" rel=\"noopener\">Подробнее: все модели reporting verbs →</a></p>\n</section>\n\n<section class=\"mv-sec\" id=\"rsp-r7\">\n  <span id=\"rs20\"></span><span id=\"rs-check\"></span>\n  <h2><span class=\"mv-num\">7</span>Проверьте пересказ</h2>\n  <p class=\"mv-lead\">Четыре шага, чтобы собрать и проверить любой пересказ.</p>\n  <ol class=\"mv-flow\">\n    <li><span class=\"mv-q\">1. Тип реплики</span><span class=\"mv-ar\">→</span><span>сообщение, вопрос или просьба</span></li>\n    <li><span class=\"mv-q\">2. Конструкция</span><span class=\"mv-ar\">→</span><span>said / told / asked или reporting verb</span></li>\n    <li><span class=\"mv-q\">3. Контекст</span><span class=\"mv-ar\">→</span><span>время, затем участники, затем день и место</span></li>\n    <li><span class=\"mv-q\">4. Итог</span><span class=\"mv-ar\">→</span><span>порядок слов, отрицание, смысл</span></li>\n  </ol>\n  <div class=\"mv-note\">Условные предложения, wish и сложные модальные значения нельзя пересказать одним списком замен. Их нужно проверять по смыслу.</div>\n  <p class=\"mv-foot\"><a class=\"rsp-more\" href=\"content/theory/reported-full.html#rs20\" target=\"_blank\" rel=\"noopener\">Подробнее: сложные случаи и самопроверка →</a></p>\n</section>\n\n</div>";
function reportedRuleHtml(prefix='') {
  const safePrefix=String(prefix).replace(/[^a-zA-Z0-9_-]/g,'');
  return REPORTED_RULE_CONTENT
    .replace(/id="([^"]+)"/g,(_,id)=>'id="'+safePrefix+id+'" data-reported-id="'+id+'"')
    .replace(/href="#(rsp-[^"]+)"/g,(_,id)=>'href="#theory/reported/'+id+'" data-reported-anchor="'+id+'"');
}
function revealReportedAnchor(container,anchor) {
  const root=container?.matches?.('.rsp')?container:container?.querySelector?.('.rsp');
  if(!root)return;
  const id=String(anchor||'').replace(/^#?(?:theory\/reported\/)?/,'');
  const target=[root,...root.querySelectorAll('[data-reported-id]')].find(node=>node.dataset.reportedId===id||node.id===id);
  if(!target)return;
  const scrollArea=root.closest('.reference-reader,.rule-dialog-content');
  const section=target.closest('.mv-sec')||target;
  if(scrollArea){
    const nav=root.querySelector('.mv-nav');
    scrollArea.scrollTop+=section.getBoundingClientRect().top-scrollArea.getBoundingClientRect().top-(nav?.getBoundingClientRect().height||0)-16;
  }else section.scrollIntoView({block:'start',behavior:'instant'});
}
function initialiseReportedRule(container) {
  const root=container?.matches?.('.rsp')?container:container?.querySelector?.('.rsp');
  if(!root||root.dataset.initialised)return;
  root.dataset.initialised='true';
  root.querySelectorAll('.mv-scroll').forEach((table,index)=>{
    table.tabIndex=0;table.setAttribute('role','region');
    table.setAttribute('aria-label',(table.closest('.mv-sec')?.querySelector('h2')?.textContent||'Таблица правила').trim()+' · таблица '+(index+1));
  });
  root.querySelectorAll('.mv-table').forEach(table=>{
    const heads=[...table.querySelectorAll('thead th')].map(th=>th.textContent.trim());
    table.querySelectorAll('tbody tr').forEach(row=>[...row.children].forEach((cell,i)=>cell.setAttribute('data-label',heads[i]||'')));
  });
  root.addEventListener('click',event=>{
    const link=event.target.closest?.('[data-reported-anchor]');
    if(!link||!root.contains(link)||event.button!==0||event.metaKey||event.ctrlKey||event.altKey||event.shiftKey)return;
    event.preventDefault();event.stopPropagation();
    revealReportedAnchor(root,link.dataset.reportedAnchor);
  });
}
